                if (((j & (uint)(0x8)) != 0))
                {
                    ((CXPLAT_TOEPLITZ_LOOKUP_TABLE*)&Toeplitz->LookupTableArray)[i].Table[j] ^= Signature1;
                }
            }
        }
    }



    public static unsafe uint CxPlatToeplitzHashCompute(CXPLAT_TOEPLITZ_HASH* Toeplitz, byte* HashInput, uint HashInputLength, uint HashInputOffset)
    {
        uint BaseOffset = HashInputOffset * (uint)(2);
        uint Result = 0;
        
        
        
        
        for (uint i = 0; ((i < HashInputLength)); i++)
        {
            Result ^= ((CXPLAT_TOEPLITZ_LOOKUP_TABLE*)&Toeplitz->LookupTableArray)[BaseOffset].Table[HashInput[i] >> 4 & 0xf];
            BaseOffset++;
            Result ^= ((CXPLAT_TOEPLITZ_LOOKUP_TABLE*)&Toeplitz->LookupTableArray)[BaseOffset].Table[HashInput[i] & 0xf];
            BaseOffset++;
        }
        return Result;
    }




